        List<String> insideParentheses = new ArrayList<>();
        Scanner scanner = new Scanner(System.in);
        int size = scanner.nextInt();
        String data = scanner.next();
        data += "^";
        int totalLength = size + 1;
        char[] buffer = new char[256];
        for (int i = 0; i < totalLength; i++) {
            buffer[i] = data.charAt(i);
        }
        int inParen = 0;
        String tempSegment = "";
        for (int i = 0; i < totalLength; i++) {
            if (buffer[i] == '(') {
                inParen = 1;
                buffer[i] = '^';
                continue;
            } else if (buffer[i] == ')') {
                inParen = 0;
                insideParentheses.add(tempSegment);
                buffer[i] = '^';
                tempSegment = "";
            }
            if (inParen == 1) {
                tempSegment += buffer[i];
                buffer[i] = '^';
            }
        }
        tempSegment = "";
        for (int i = 0; i < totalLength; i++) {
            if (buffer[i] == '^') {
                if (tempSegment.length() == 0) continue;
                mainParts.add(tempSegment);
                tempSegment = "";
            } else {
                tempSegment += buffer[i];
            }
        }
        int maxLetters = 0;
        int totalWords = 0;
        for (String part : mainParts) {
            String s = part + "_";
            int letterCount = 0;
            for (int j = 0; j < s.length(); j++) {
                if (Character.isLetter(s.charAt(j))) {
                    letterCount++;
                } else if (s.charAt(j) == '_') {
                    maxLetters = Math.max(maxLetters, letterCount);
                    letterCount = 0;
                }
            }
        }
        int wordCount = 0;
        for (String segment : insideParentheses) {
            String s = segment + "_";
            String wordBuilder = "";
            for (int j = 0; j < s.length(); j++) {
                if (Character.isLetter(s.charAt(j))) {
                    wordBuilder += s.charAt(j);
                } else if (s.charAt(j) == '_' && !wordBuilder.isEmpty()) {
                    wordBuilder = "";
                    wordCount++;
                }
            }
        }
        System.out.println(maxLetters + " " + wordCount);
    }
}
